n30570.content:
\begin{lemma}[Directing measure is probability (L$^2$ version)]
  \label{lem:directing_measure_isProb_L2}
  \lean{Exchangeability.DeFinetti.ViaL2.directing_measure_isProbabilityMeasure}
  \leanok
  The Stieltjes measure constructed from the limiting CDF is a probability measure
  for every $\omega$ (pointwise, not merely a.e.). Monotonicity, bounds, and
  right-continuity of the underlying CDF are inherited directly from mathlib's
  \texttt{stieltjesOfMeasurableRat} construction.
\end{lemma}

n30571.content:
\begin{theorem}[Directing measure equals \texttt{condExpKernel} push-forward]
  \label{thm:directing_measure_ae_eq_condExpKernel_map}
  \lean{Exchangeability.DeFinetti.ViaL2.directing_measure_ae_eq_condExpKernel_map}
  \leanok
  \uses{lem:directing_measure_isProb_L2}
  Almost everywhere in $\omega$, the Stieltjes-built directing measure coincides
  with the push-forward of mathlib's \texttt{condExpKernel}~$\mu$~$\mathcal{T}$~$\omega$
  by $X_0$. This is the kernel-level bridge from the analytic L$^2$ construction
  to mathlib's conditional-expectation kernel API.
\end{theorem}

n30572.content:
\begin{lemma}[Directing-measure integral equals conditional expectation]
  \label{lem:directing_measure_integral_eq_condExp}
  \lean{Exchangeability.DeFinetti.ViaL2.directing_measure_integral_eq_condExp}
  \leanok
  \uses{thm:directing_measure_ae_eq_condExpKernel_map}
  For a bounded measurable function $f$, the integral
  $\int f \, d\nu(\omega)$ against the directing measure equals
  $\mathbb{E}[f \circ X_0 \mid \mathcal{T}](\omega)$ almost everywhere. This is the
  shape consumed by the shared common-ending step.
\end{lemma}

